/* ══════════════════════════════════════════════════════
   CAMPUS LIFE
══════════════════════════════════════════════════════ */
.campus-life {
  max-width: 960px;
  margin: 0 auto;
  padding: 64px 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.campus-life-left {}
.campus-big-text {
  font-size: 4rem;
  font-weight: 900;
  color: var(--green-link);
  letter-spacing: -0.02em;
  line-height: 1;
  display: inline;
}
.campus-life-word {
  font-size: 2.2rem;
  font-weight: 400;
  color: var(--text-dark);
  margin-left: 8px;
  display: inline;
}
.campus-life-header { margin-bottom: 16px; }
.campus-life-sub {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-dark);
  margin-bottom: 12px;
}
.campus-life-body {
  font-size: 0.8rem;
  color: var(--text-mid);
  line-height: 1.7;
  margin-bottom: 10px;
}
.campus-life-link {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--green-link);
  border-bottom: 1px solid var(--green-link);
  padding-bottom: 1px;
  margin-top: 8px;
  transition: opacity 0.2s;
}
.campus-life-link:hover { opacity: 0.75; }
.campus-life-right {}
.campus-pool-img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  border-radius: 4px;
}

/* ══════════════════════════════════════════════════════
   WIDE POOL IMAGE STRIP
══════════════════════════════════════════════════════ */
.wide-strip {
  width: 100%;
  height: 320px;
  overflow: hidden;
}
.wide-strip img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 40%;
}

/* ═════════════════════════════════════════════════════
   STATS BAR
══════════════════════════════════════════════════════ */
.stats-bar {
  background: var(--green-dark);
  padding: 40px 24px;
  display: flex;
  justify-content: center;
  gap: 0;
}
.stat-item {
  flex: 1;
  max-width: 200px;
  text-align: center;
  padding: 0 12px;
  border-right: 1px solid rgba(255,255,255,0.15);
}
.stat-item:last-child { border-right: none; }
.stat-num {
  font-size: 2.6rem;
  font-weight: 800;
  color: var(--white);
  line-height: 1;
  margin-bottom: 8px;
}
.stat-label {
  font-size: 0.7rem;
  color: rgba(255,255,255,0.72);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  line-height: 1.4;
}

/* ══════════════════════════════════════════════════════
   CULTURAL WEEK
══════════════════════════════════════════════════════ */
.cultural-wrap {
  position: relative;
  padding-bottom: 80px;
}
.cultural-section {
  max-width: 960px;
  margin: 0 auto;
  padding: 64px 24px 32px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: start;
}
.cultural-left {}
.cultural-heading {
  font-size: 2rem;
  font-weight: 800;
  color: var(--text-dark);
  line-height: 1.2;
  margin-bottom: 20px;
}
.cultural-body {
  font-size: 0.8rem;
  color: var(--text-mid);
  line-height: 1.7;
  margin-bottom: 16px;
}
.cultural-link {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--green-link);
  border-bottom: 1px solid var(--green-link);
  padding-bottom: 1px;
  transition: opacity 0.2s;
}
.cultural-link:hover { opacity: 0.75; }
.cultural-right { position: relative; }
.cultural-img-main {
  width: 100%;
  height: 320px;
  object-fit: cover;
  border-radius: 4px;
}
.cultural-img-float {
  position: absolute;
  bottom: -80px;
  right: -20px;
  width: 160px;
  height: 200px;
  object-fit: cover;
  border: 4px solid var(--white);
  border-radius: 4px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.15);
}
